// STAGE 2 — Verify the webhook really came from Shopify (HMAC-SHA256).
// Mirrors integrations/shopify.py verify_webhook_hmac(). Reject fakes so no
// money-spending run is ever triggered by a forged 'paid' order.
const crypto = require('crypto');
const item = items[0];
const secret = $env.SHOPIFY_WEBHOOK_SECRET;
if (!secret) throw new Error('SHOPIFY_WEBHOOK_SECRET not set in environment.');

// Raw body bytes captured by the Webhook node (rawBody = true).
const raw = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64')
  : Buffer.from(JSON.stringify(item.json.body || item.json), 'utf8');

const headers = item.json.headers || {};
const sig = headers['x-shopify-hmac-sha256'] || headers['X-Shopify-Hmac-Sha256'] || '';
const digest = crypto.createHmac('sha256', secret).update(raw).digest('base64');

const a = Buffer.from(digest);
const b = Buffer.from(String(sig).trim());
const ok = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!ok) throw new Error('Shopify HMAC verification FAILED — rejecting webhook.');

// Parse the verified order for downstream stages.
let order;
try { order = JSON.parse(raw.toString('utf8')); }
catch (e) { order = item.json.body || item.json; }
return [{ json: { verified: true, shopifyOrder: order } }];

// STAGE 3 — Build the RETOLD order object from the Shopify order.
// Mirrors integrations/shopify.py order_to_retold(). Decides book vs book_film
// from line-item SKUs, and pulls intake props / note_attributes if present.
const so = items[0].json.shopifyOrder;
const li = so.line_items || [];
const skus = li.map(x => (x.sku || '').toLowerCase());
const isFilm = skus.some(s => s.includes('film'));

const props = {};
for (const item of li) for (const p of (item.properties || [])) if (p.name) props[p.name] = p.value;
for (const na of (so.note_attributes || [])) if (na.name) props[na.name] = na.value;
const first = (...keys) => { for (const k of keys) if (props[k]) return props[k]; return null; };

let by = first('birth_year', 'Birth year');
by = by ? parseInt(by, 10) : null;
let gk = first('grandchildren', 'Grandchildren');
if (typeof gk === 'string') gk = gk.split(',').map(s => s.trim()).filter(Boolean);

const order = {
  order_id: String(so.id || so.order_id),
  order_number: so.name,
  sku: isFilm ? 'book_film' : 'book',
  customer_email: so.email || (so.customer && so.customer.email) || '',
  subject: {
    name: first('subject_name', 'Name', 'Parent name') || '',
    relation: first('relation', 'Relation') || '',
    birth_year: Number.isFinite(by) ? by : null,
  },
  grandchildren: gk || [],
  notes: first('notes', 'Notes') || '',
  shipping_address: so.shipping_address || {},
};
return [{ json: { order } }];

// Parse the engine's book.json + voice_page.json from stdout.
const out = items[0].json.stdout || items[0].json;
const parsed = typeof out === 'string' ? JSON.parse(out) : out;
return [{ json: parsed }];

// Automated proof gate. The engine's SEPARATE honesty pass wrote
// book._qc = { clean: bool, issues: [...] }. We auto-approve a clean
// book, and HOLD (approved=false) only when a possible fabrication was
// flagged — the one safety catch that protects the 'never invented'
// promise and real print spend.
const book = $node['8c · Parse book'].json.book || $json.book || $json;
const qc = (book && book._qc) || { clean: false, issues: ['no _qc found'] };
const approved = qc.clean === true;
return [{ json: { approved, qc, order_id: book.order_id,
  reason: approved ? 'honesty QC clean — auto-approved'
    : ('held for review — ' + (qc.issues||[]).length + ' flag(s)') } }];
